let seed;
let mySize, margin;
let num;
let myGraphic;
let palette, color_bg;
let str_wei;

let unit_x, unit_y;
let count;
let t;
let mods = [];
let a, b, c;

function setup() {
	a = TAU / TAU;
	b = a + a;
	c = a - a;
	seed = Math.random() * sq(sq(sq(int(TAU))));
	randomSeed(seed);

	mySize = max(windowWidth, windowHeight) * 0.9;
	createCanvas(windowWidth, windowHeight, WEBGL);

	// perspective(0.5, width / height, 0.1, 5000);
	perspective(1, width / height, 1, 12000);
	// ortho(-width / 2, width / 2, -height / 2, height / 2, -mySize, max(width, height) + mySize)
	palette = random(colorScheme).colors.concat();
	color_bg = random(bgcolor);
	background(color_bg);
	frameRate(25);
	t = rez = c = n = c;
}

function drawHollowHemisphere(r, seg) {
	for (let i = 0; i < seg; i++) {
		let angleStart = map(i, 0, seg, 0, TWO_PI / 24);
		let angleEnd = map(i + 1, 0, seg, 0, TWO_PI / 2);

		arc(0, random(1, 1), r / 1 * random(0.1, 0.1), r / 1 * random(0.1, 0.1), angleStart, angleEnd);
		rotateX(TAU/seg + frameCount / 1000);
		rotateY(TAU/seg + frameCount / 1000);
		rotateZ(TAU/seg + frameCount / 1000);
	}
}

function drawArc(r, startAngle, endAngle, zOffset) {
	beginShape();
	for (let angle = startAngle; angle <= endAngle; angle += 0.01) {
		let x = r * cos(angle);
		let y = r * sin(angle);
		let z = -zOffset * 1 * sin(angle);
		vertex(x, y, z);
	}
	endShape();
}

function draw() {
	let c = color(255, 255, 255, 100);
	let c2 = color(255, 255, 255, 50);
	let lightDir1 = createVector(0, 0, -1);
	let lightDir2 = createVector(1, -1, 1);
	let lightDir3 = createVector(-1, 1, 1);
	// directionalLight(c, lightDir1);
	// directionalLight(c2, lightDir1);
	// directionalLight(c2, lightDir2);
	// directionalLight(c2, lightDir3);

	randomSeed(seed);
	background(color_bg);
	// translate(sin(1 * t / 100 - t / 2) * random(100, 1000), cos(2 * t / 1) * random(100, 100), sin(10 * t / 1 + t) * random(100, 1000));

	push();
	translate(0, 0, mySize * 0.25);
	rotateX(random(TAU));
	rotateY(random(TAU));
	rotateZ(random(TAU));

	rotateX(random([-1, 1]) * frameCount / random(100, 200) / 1);
	rotateY(random([-1, 1]) * frameCount / random(100, 200) / 1);
	rotateZ(random([-1, 1]) * frameCount / random(100, 200) / 1);


	let cubeSize = mySize / 100;
	let plus = cubeSize / 1;

	for (let i = -cubeSize / b; i < cubeSize / b + plus; i += plus * a) {
		for (let j = -cubeSize / b; j < cubeSize / b + plus; j += plus * a) {
			for (let k = -cubeSize / b; k < cubeSize / b + plus; k += plus * a) {

				strokeCap(PROJECT);
				n = noise(i * rez + t, j * rez + t, k * rez + t) * random(0.1, 0.3) / 0.1;
				push();
				rotateX(i * TAU);
				rotateY(j * TAU);
				rotateZ(k * TAU);
				rotateX(random([-1, 1]) * frameCount / 200);
				rotateY(random([-1, 1]) * frameCount / 200);
				rotateZ(random([-1, 1]) * frameCount / 250);
				translate(i * n, j * n, k * n);
				translate(i * 1, j * 1, k * 1);
				let planeSize = mySize / 2 / random([16, 4, 8]);

				beginShape();
				for (let t = 0; t <= 50; t++) {
					var x = planeSize / 0.25 * cos(t);
					var y = planeSize / 0.25 * sin(t);
					var z = planeSize * 2 * cos(t * 2);
					noFill();
					stroke(random(palette));
					strokeWeight(random(a, b) * 1 / random(1, 0.5) / random(1, 1));
					rotateX(random([-1, 1]) * frameCount / 500);
					rotateY(random([-1, 1]) * frameCount / 500);
					rotateZ(random([-1, 1]) * frameCount / 500);
					// curveVertex(x, y, z);
				}

				endShape(CLOSE);

				// rotateX(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				// rotateY(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
				// rotateZ(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));

				let px = plus / random(a, int(TAU)) / b / sin(n) / random(1, 5);
				let py = plus / random(a, int(TAU)) / b / cos(n) / random(1, 5);
				let pz = plus / random(a, int(TAU)) / b / tan(n) / random(1, 5);
				push();
				noStroke();
				fill(random(palette));
				translate(px, py, pz);
				stroke(random(palette));
				strokeWeight(random(a, b) * 1 / 0.2 / random(1, 5));
				rotateX(random([-1, 1]) * frameCount / 50);
				rotateY(random([-1, 1]) * frameCount / 50);
				rotateZ(random([-1, 1]) * frameCount / 50);
				// line(0, 0, 0, px, py, pz);
				noStroke();
				fill(random(palette));
				// sphere(mySize / random(25, 50));
				translate(px, py, pz);
				// noStroke();
				// fill(random(palette));


				rotateX(random([-1, 1]) * frameCount / 500);
				rotateY(random([-1, 1]) * frameCount / 500);
				rotateZ(random([-1, 1]) * frameCount / 500);
				noFill();
				stroke(random(palette));
				strokeWeight(random(a, b) * 0.5 / random(0.1, 0.2) / random(1, 5));
				drawArc(mySize / random(2, 5), -(PI / 2), random(PI / 2), random(mySize / 20, mySize / 20))

				strokeWeight(random(a, b) * 0.025 / 0.1 / random(1, 5));

				noStroke();
				fill(random(palette));
				// translate(0, 0, mySize / 2);
				// torus(mySize * random(0.25, 0.75), random(1, 5), 60);

				pop();

				noFill();
				stroke(random(palette));
				// translate(px, py, pz);
				rotateX(random([-1, 1]) * frameCount / 100);
				rotateY(random([-1, 1]) * frameCount / 100);
				rotateZ(random([-1, 1]) * frameCount / 100);
				drawHollowHemisphere(planeSize / 0.02, 32)

				beginShape();
				for (let t = 0; t <= TWO_PI * 1; t += 1) {
					var x = planeSize / 0.25 * cos(t);
					var y = planeSize / 0.25 * sin(t);
					var z = planeSize * 2 * cos(t * 2);
					// let x = noise(t + i * 0.1) * planeSize / 0.01 - 0;
					// let y = noise(t + i * 0.2) * planeSize / 0.01 - 0;
					// let z = noise(t + i * 0.1) * planeSize / 0.01 - 0;
					strokeWeight(random(a, b) * 6 / random(1, 0.5) / random(1, 1));
					// line(0,0,0,random(x), random(y), random(z));
					rotateX(random([-1, 1]) * frameCount / 500);
					rotateY(random([-1, 1]) * frameCount / 500);
					rotateZ(random([-1, 1]) * frameCount / 500);
					point(x, y, z);
					// line(-x, y, -z,x, y, z);
					// curveVertex(x, y, z);
					// vertex(-x, y, -z);
				}

				endShape(CLOSE);

				pop();
			}
		}
	}
	pop();
	t += 0.1 / random(10, 1) / random(3, 7) / 10;
}

